import { adminDb } from '@/lib/firebase-admin';
import type { AdminSession } from '@/lib/get-admin-session';

/** "Name (email)" for the report's "Generated by" line; the email alone
 *  when the admin record has no name. Never throws. */
export async function reportActor(session: AdminSession): Promise<string> {
  const email = session.email ?? 'unknown admin';
  try {
    const snap = await adminDb.collection('admins').doc(session.uid).get();
    const name = String(snap.get('name') ?? snap.get('displayName') ?? '').trim();
    return name ? `${name} (${email})` : email;
  } catch {
    return email;
  }
}
